===== Note crumb logic =====

const { title, type, description, updated, domain, slug, headings, backlinks, active } = Astro.props;

// Breadcrumb from the folder slug: "wiki/Concepts/Higher-Order-Generativity" →
// "wiki / Concepts / Higher-Order Generativity" (DS .crumb / NotePage breadcrumb).
const crumbParts = slug
  .replace(/^\/+/, '')
  .replace(/\/+$/, '')
  .split('/')
  .filter(Boolean)
  .map((p) => p.replace(/--and--/g, ' & ').replace(/-+/g, ' '));
const breadcrumb = crumbParts.length ? crumbParts.join(' / ') : title;
// Each crumb is a link (owner, 2026-09-05). A folder crumb lists that folder.
// journal, personal, and projects keep their section landings. The page title stays plain text.
// journal / personal / projects keep their section landings.
const LANDING: Record<string, string> = {
  journal: '/journal/',
  personal: '/personal/',
  projects: '/projects/',
  notes: '/notes/',
};
const slugParts = slug.replace(/^\/+/, '').replace(/\/+$/, '').split('/').filter(Boolean);
const crumbs = slugParts.map((part, i) => {
  const label = part.replace(/--and--/g, ' & ').replace(/-+/g, ' ');
  if (i === slugParts.length - 1) return { label, href: null as string | null };
  if (i === 0 && LANDING[part]) return { label, href: LANDING[part] };
  return { label, href: `/folder/${slugParts.slice(0, i + 1).join('/')}/` };
});

